#include <iostream>
using namespace std;

class Purse {
public:
    Purse() {
        coins = 0;
    }

    void put(int k) {
        coins = coins + k;
    }

    bool take(int k) {
        if (k > coins) {
            return false;
        }
        coins = coins - k;
        return true;
    }

    int total() const {
        return coins;
    }

private:
    int coins;
};

int main() {
    int n = 0;
    if (!(cin >> n)) {
        return 1;
    }

    Purse purse;
    for (int i = 0; i < n / 2; i++) {
        int code = 0;
        int amount = 0;
        cin >> code >> amount;
        if (code == 1) {
            purse.put(amount);
            cout << "存进 " << amount << " 条，现在有 " << purse.total() << " 条喵" << endl;
        } else {
            if (purse.take(amount)) {
                cout << "取出 " << amount << " 条，还剩 " << purse.total() << " 条喵" << endl;
            } else {
                cout << "取不出来，只有 " << purse.total() << " 条喵" << endl;
            }
        }
    }

    cout << "打烊啦，罐子里有 " << purse.total() << " 条喵" << endl;
    return 0;
}

